import pytest
import click


def test_func_param_type_value_error_message(runner):
    class MyClass:
        def __init__(self, value):
            self.value = value

        @staticmethod
        def from_str(input_value):
            if input_value != "works":
                raise ValueError(f"input was {input_value!r}, should be 'works'")
            return MyClass(input_value)

    @click.command()
    @click.argument("mydata", type=click.types.FuncParamType(MyClass.from_str))
    def cli(mydata):
        click.echo(f"Success: {mydata.value}")

    result = runner.invoke(cli, ["fails"])
    assert result.exit_code == 2
    assert "Error: Invalid value: input was 'fails', should be 'works'" in result.output

import unittest

from sqlglot import parse_one
from sqlglot.errors import ParseError


class TestDatabricks(unittest.TestCase):
    def test_insert_replace_using(self):
        sql = """
        INSERT INTO TABLE students
            REPLACE USING (country)
            SELECT * FROM new_students;
        """
        try:
            expression = parse_one(sql, dialect="databricks")
            self.assertIsNotNone(expression)
            self.assertEqual(
                expression.sql(dialect="databricks"),
                "INSERT INTO TABLE students REPLACE USING (country) SELECT * FROM new_students",
            )
        except ParseError as e:
            self.fail(f"Parsing failed with ParseError: {e}")

import unittest

from sqlglot import parse_one, exp
from sqlglot.errors import ParseError


class TestIssue8225(unittest.TestCase):
    def test_create_table_auto_increment(self):
        sql = """CREATE TABLE t1(id INT KEY AUTO_INCREMENT);"""
        try:
            ast = parse_one(sql, read="mysql")
            self.assertIsInstance(ast, exp.Create)
            self.assertEqual(
                ast.sql(dialect="mysql"), "CREATE TABLE t1 (id INT PRIMARY KEY AUTO_INCREMENT)"
            )
        except ParseError as e:
            self.fail(f"Parsing failed with ParseError: {e}")

    def test_create_table_auto_increment_with_primary_key(self):
        sql = """CREATE TABLE t1(id INT PRIMARY KEY AUTO_INCREMENT);"""
        try:
            ast = parse_one(sql, read="mysql")
            self.assertIsInstance(ast, exp.Create)
            self.assertEqual(
                ast.sql(dialect="mysql"), "CREATE TABLE t1 (id INT PRIMARY KEY AUTO_INCREMENT)"
            )
        except ParseError as e:
            self.fail(f"Parsing failed with ParseError: {e}")
